-- Fase 9b: 15 países más, en los 5 continentes. Esta migración es SOLO DE DATOS: no cambia tablas ni código.
-- Así se agrega un país: una fila en countries con su área. Si su moneda es nueva, una fila en currencies y sus
-- tarifas base (currency_rates y currency_vehicle_rates). Para deshacer: borrar estas filas.

-- Tres monedas nuevas: dólar australiano, rupia india y rand sudafricano
INSERT INTO `currencies` (`code`, `decimals`, `fare_step`, `min_fare`, `max_fare`) VALUES
    ('AUD', 2, 1, 5, 7500),
    ('INR', 2, 50, 200, 400000),
    ('ZAR', 2, 10, 50, 90000);

INSERT INTO `currency_rates` (`currency_code`, `km_value`, `min_value`, `weight_rate`, `size_rate`, `commission_rate`) VALUES
    ('AUD', 2.2, 0.75, 0.08, 7, 0.1),
    ('INR', 25, 5, 2, 150, 0.1),
    ('ZAR', 18, 5, 0.8, 60, 0.1);

INSERT INTO `currency_vehicle_rates` (`currency_code`, `vehicle_type`, `base_fare`, `km_factor`)
    SELECT C.`code`, V.`vehicle_type`,
        CASE C.`code`
            WHEN 'AUD' THEN ELT(FIELD(V.`vehicle_type`, 'CARRY', 'ESTACAS', 'FURGON', 'CAMION'), 45, 60, 90, 150)
            WHEN 'INR' THEN ELT(FIELD(V.`vehicle_type`, 'CARRY', 'ESTACAS', 'FURGON', 'CAMION'), 400, 600, 900, 1500)
            WHEN 'ZAR' THEN ELT(FIELD(V.`vehicle_type`, 'CARRY', 'ESTACAS', 'FURGON', 'CAMION'), 300, 450, 650, 1100)
        END,
        V.`km_factor`
    FROM `currencies` AS C CROSS JOIN `currency_vehicle_rates` AS V
    WHERE C.`code` IN ('AUD', 'INR', 'ZAR') AND V.`currency_code` = 'COP';

-- El área de cada país va en su fila (generada con scripts/countries/build-areas.mjs a partir de Natural Earth).
-- Hispanohablantes con dólar, euro con uno de los idiomas de la app, y Australia, India y Sudáfrica en inglés
